import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const wasmPath = resolve(root, 'node_modules/sql.js/dist/sql-wasm.wasm');
const outPath = resolve(root, 'server/sqlite-wasm-b64.ts');

const b64 = readFileSync(wasmPath).toString('base64');
writeFileSync(
  outPath,
  '// Generated by scripts/gen-sqlite-wasm.mjs — do not edit by hand.\n' +
    '// sql.js WASM binary inlined as base64 (keeps the build native-free).\n' +
    `export default "${b64}";\n`,
);
console.log(`wrote ${outPath} (${b64.length} chars)`);
